import{d as g,C as r,o as h,c as d,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第20章","description":"《中庸》第 20 章——哀公问政：为政在人、取人以身；仁义与礼所生；五达道三达德；九经；诚者天之道，为学五步与「人一能之己百之」。","frontmatter":{"title":"中庸·第20章","description":"《中庸》第 20 章——哀公问政：为政在人、取人以身；仁义与礼所生；五达道三达德；九经；诚者天之道，为学五步与「人一能之己百之」。","category":"guide","aliases":["第20章","中庸第20章","哀公问政"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-20.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-20.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-20.md"},z=g({...u,setup(p){const o=[{id:"weizheng",label:"哀公问政 · 为政在人，取人以身",showLabel:!0,sentences:[["哀公问政。子曰：“文武之政，布在",{text:"方策",glossary:"fangce"},"。其人存，则其政举；其人亡，则其政息。人道",{text:"敏政",glossary:"minzheng"},"，地道敏树。夫政也者，",{text:"蒲卢",glossary:"pulu"},"也。故为政在人，取人以身，修身以道，修道以仁。"]],note:"鲁哀公问政。孔子说：文王、武王的政事都记载在方策（典籍）上，然而「其人存，则其政举；其人亡，则其政息」——有那样的人在，政就推行；人不在，政也就止息。以「人道敏政，地道敏树」作比（敏＝速），又说「夫政也者，蒲卢也」（蒲卢，蒲苇，易生之物）。归结为「为政在人，取人以身，修身以道，修道以仁」——全章之纲，层层递推。"},{id:"renyi",label:"仁者人也 · 亲亲之杀，尊贤之等 · 不可以不知天",showLabel:!0,sentences:[["仁者人也，亲亲为大；义者宜也，尊贤为大；亲亲之",{text:"杀",glossary:"shai"},"，尊贤之等，礼所生也。在下位不获乎上，民不可得而治矣！故君子不可以不修身；思修身，不可以不事亲；思事亲，不可以不知人；思知人，不可以不知天。”"]],note:"「仁者人也，亲亲为大；义者宜也，尊贤为大」——仁即人之所以为人，以亲爱亲人为大；义即合宜，以尊崇贤者为大。由「亲亲之杀（等差）、尊贤之等」而礼由此生。又逆推一层：「故君子不可以不修身；思修身，不可以不事亲；思事亲，不可以不知人；思知人，不可以不知天。」"},{id:"dadao",label:"五达道 · 三达德 · 好学力行知耻",showLabel:!0,sentences:[["天下之",{text:"达道",glossary:"dadao"},"五，所以行之者三：曰君臣也，父子也，夫妇也，昆弟也，朋友之交也：五者天下之达道也。知、仁、勇三者，天下之",{text:"达德",glossary:"dade"},"也，所以行之者一也。或生而知之，或学而知之，或困而知之，及其知之一也；或安而行之，或利而行之，或勉强而行之，及其成功一也。"],["子曰：“好学近乎知，力行近乎仁，知耻近乎勇。知斯三者，则知所以修身；知所以修身，则知所以治人；知所以治人，则知所以治天下国家矣。”"]],note:"「天下之达道五」：君臣、父子、夫妇、昆弟、朋友之交——五者是人共由之道。「所以行之者三」：知、仁、勇——三者是天下通行之德（达德）；「所以行之者一也」（一，即诚）。又「或生而知之，或学而知之，或困而知之，及其知之一也」，以及安行、利行、勉强而行，「及其成功一也」。下文孔子续说：「好学近乎知，力行近乎仁，知耻近乎勇」——知此三者，则知所以修身、治人、治天下国家。"},{id:"jiujing",label:"凡为天下国家有九经",showLabel:!0,sentences:[["凡为天下国家有",{text:"九经",glossary:"jiujing"},"，曰：修身也，尊贤也，亲亲也，敬大臣也，体群臣也，子庶民也，来百工也，柔远人也，怀诸侯也。修身则道立，尊贤则不惑，亲亲则诸父昆弟不怨，敬大臣则不",{text:"眩",glossary:"xuan"},"，体群臣则士之报礼重，子庶民则百姓",{text:"劝",glossary:"quan"},"，来百工则财用足，柔远人则四方归之，怀诸侯则天下畏之。"]],note:"「凡为天下国家有九经」（经＝常道）：修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯。随即列九者的效验：修身则道立，尊贤则不惑，亲亲则诸父昆弟不怨，敬大臣则不眩，体群臣则士之报礼重，子庶民则百姓劝，来百工则财用足，柔远人则四方归之，怀诸侯则天下畏之。"},{id:"jiujingmu",label:"九经之目 · 所以行之者一也",showLabel:!0,sentences:[["齐明盛服，非礼不动，所以修身也；去谗远色，贱货而贵德，所以劝贤也；尊其位，重其禄，同其好恶，所以劝亲亲也；官盛任使，所以劝大臣也；忠信重禄，所以劝士也；时使薄敛，所以劝百姓也；日省月试，既",{text:"禀称事",glossary:"linchen"},"，所以劝百工也；送往迎来，嘉善而矜不能，所以柔远人也；继绝世，举废国，治乱持危，朝聘以时，厚往而薄来，所以怀诸侯也。凡为天下国家有九经，所以行之者一也。"]],note:"列九经之「目」（具体做法）：齐明盛服、非礼不动，所以修身；去谗远色、贱货贵德，所以劝贤；尊其位、重其禄、同其好恶，所以劝亲亲；官盛任使，所以劝大臣；忠信重禄，所以劝士；时使薄敛，所以劝百姓；日省月试、既禀称事（俸禄与事功相称），所以劝百工；送往迎来、嘉善而矜不能，所以柔远人；继绝世、举废国、治乱持危、朝聘以时、厚往而薄来，所以怀诸侯。末句「所以行之者一也」——一，即诚。"},{id:"yuzhe",label:"凡事豫则立 · 诚身有道 · 诚者天之道",showLabel:!0,sentences:[["凡事",{text:"豫",glossary:"yu"},"则立，不豫则废。言前定则不",{text:"跲",glossary:"jia"},"，事前定则不困，行前定则不",{text:"疚",glossary:"jiu"},"，道前定则不穷。在下位不获乎上，民不可得而治矣；获乎上有道：不信乎朋友，不获乎上矣；信乎朋友有道：不顺乎亲，不信乎朋友矣；顺乎亲有道：",{text:"反诸身不诚",glossary:"fanzhushen"},"，不顺乎亲矣；诚身有道：不明乎善，不诚乎身矣。"],["诚者，天之道也；诚之者，人之道也。诚者不勉而中，不思而得，",{text:"从容中道",glossary:"congrong"},"，圣人也。诚之者，",{text:"择善而固执之",glossary:"zeshan"},"者也。"]],note:"「凡事豫则立，不豫则废」：言前定则不跲（不绊跌），事前定则不困，行前定则不疚，道前定则不穷。又层层推求：「在下位不获乎上，民不可得而治矣」——获上有道，在于信乎朋友；信友有道，在于顺乎亲；顺亲有道，在于反诸身而诚；诚身有道，在于明乎善。末段立「诚」之二义：「诚者，天之道也」——不勉而中、不思而得、从容中道，是圣人；「诚之者，人之道也」——择善而固执之，是学者功夫。"},{id:"weixue",label:"博学审问慎思明辨笃行 · 人一能之己百之",showLabel:!0,sentences:[["博学之，审问之，慎思之，明辨之，笃行之。有弗学，学之弗能",{text:"弗措",glossary:"fucuo"},"也；有弗问，问之弗知弗措也；有弗思，思之弗得弗措也；有弗辨，辨之弗明弗措也；有弗行，行之弗笃弗措也；人一能之己百之，人十能之己千之。果能此道矣，虽愚必明，虽柔必强。"]],note:"为学之序五项：「博学之，审问之，慎思之，明辨之，笃行之」。又有五项「弗措」（不罢休）：有弗学，学之弗能弗措也……有弗行，行之弗笃弗措也。「人一能之，己百之；人十能之，己千之」——别人一遍能，自己就做百遍；别人十遍能，自己就做千遍。「果能此道矣，虽愚必明，虽柔必强。」"}],s=[{id:"fangce",term:"方策",pinyin:"fāng cè",meaning:"方：木板；策：竹简。布在方策，谓政事布列于典籍之上。"},{id:"minzheng",term:"敏政",pinyin:"mǐn zhèng",meaning:"敏：速。人道敏政、地道敏树——犹言人敏于政，地敏于树。"},{id:"pulu",term:"蒲卢",pinyin:"pú lú",meaning:"蒲苇，易生之物。一说为蜾蠃（细腰蜂）。喻政之易生。"},{id:"shai",term:"亲亲之杀",pinyin:"qīn qīn zhī shài",meaning:"杀：等差、降杀（读 shài）。亲亲有等差，尊贤有等级，礼由此而生。"},{id:"dadao",term:"达道",pinyin:"dá dào",meaning:"天下通行之道，共五者：君臣、父子、夫妇、昆弟、朋友之交。"},{id:"dade",term:"达德",pinyin:"dá dé",meaning:"天下通行之德，共三者：知、仁、勇。所以行之者一也——朱注谓「一」即诚。"},{id:"jiujing",term:"九经",pinyin:"jiǔ jīng",meaning:"为天下国家的九条常道：修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯。"},{id:"xuan",term:"眩",pinyin:"xuàn",meaning:"迷惑。敬大臣则不眩——事有大臣任之，故不迷乱。"},{id:"quan",term:"劝",pinyin:"quàn",meaning:"勉励、鼓励。"},{id:"linchen",term:"既禀称事",pinyin:"jì lǐn chèn shì",meaning:"既：同「饩」（廪食）；禀：给。谓所给之食与其事相称。"},{id:"yu",term:"豫",pinyin:"yù",meaning:"预先。凡事豫则立，不豫则废。"},{id:"jia",term:"跲",pinyin:"jiá",meaning:"绊倒、窒碍。言前定则不跲——话先说定，就不会陷入窘境。"},{id:"jiu",term:"疚",pinyin:"jiù",meaning:"病、不安。行前定则不疚。"},{id:"fanzhushen",term:"反诸身不诚",pinyin:"fǎn zhū shēn bù chéng",meaning:"反求于自身而不真实无妄。"},{id:"congrong",term:"从容中道",pinyin:"cōng róng zhòng dào",meaning:"从容自然而合乎中道。中：读 zhòng（合）。"},{id:"zeshan",term:"择善而固执之",pinyin:"zé shàn ér gù zhí zhī",meaning:"选择善而坚定持守——朱注：「诚之者，择善而固执之者也。」即贤人由明而诚的功夫。"},{id:"fucuo",term:"弗措",pinyin:"fú cuò",meaning:"不放下、不罢休。学之弗能弗措——不学到会，绝不放下。"}];return(y,n)=>{const l=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第20章",tabindex:"-1"},[e("中庸·第20章 "),i("a",{class:"header-anchor",href:"#中庸·第20章","aria-label":'Permalink to "中庸·第20章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第二十章是全篇最长的一章（「哀公问政」）：由为政之道说起——"),i("strong",null,"为政在人，取人以身，修身以道，修道以仁"),e("；再列仁义礼三者的关系、五达道与三达德、九经；最后落到「"),i("strong",null,"诚"),e("」与为学五步。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"为政在人 · 五达道三达德 · 九经 · 诚者天之道",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第20章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"方策",pinyin:["fāng","cè"],meaning:"方：木板；策：竹简。布在方策，谓政事布列于典籍。"},{term:"敏政",pinyin:["mǐn","zhèng"],meaning:"敏：速。人道敏政，犹言人敏于政。"},{term:"蒲卢",pinyin:["pú","lú"],meaning:"蒲苇，易生之物。喻政易生而速成。"},{term:"亲亲之杀",pinyin:["qīn","qīn","zhī","shài"],meaning:"杀：等差（读 shài）。亲亲有等差、尊贤有等级，礼由此生。"},{term:"达道",pinyin:["dá","dào"],meaning:"天下通行之道，有五：君臣、父子、夫妇、昆弟、朋友。"},{term:"达德",pinyin:["dá","dé"],meaning:"天下通行之德，有三：知、仁、勇。"}]}),a(t,{items:[{term:"九经",pinyin:["jiǔ","jīng"],meaning:"修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯——为天下国家的九条常道。"},{term:"豫",pinyin:["yù"],meaning:"预先。凡事豫则立，不豫则废。"},{term:"择善而固执之",pinyin:["zé","shàn","ér","gù","zhí","zhī"],meaning:"择善而坚定持守——贤人「由明而诚」的功夫（朱注）。"},{term:"弗措",pinyin:["fú","cuò"],meaning:"不放下、不罢休。"},{term:"人一能之己百之",pinyin:["rén","yī","néng","zhī","jǐ","bǎi","zhī"],meaning:"别人一遍能，自己就做一百遍——困知勉行者的功夫。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>哀公问政 · 为政在人</strong>：哀公问政。孔子说：「文王武王的政事，布列在典籍上。有那样的人，政就实行；没有那样的人，政就停止。人道敏于政，地道敏于树，政就像蒲苇一样易生。所以为政在于得人，得人在于修身，修身在于道，修道在于仁。」</p><p><strong>仁者人也 · 不可以不知天</strong>：仁，就是人（之所以为人），以亲爱亲族为大；义，就是宜，以尊重贤者为大。亲亲有等差、尊贤有等级，礼由此而生。在下位得不到上位者的信任，百姓就不可能治理好。所以君子不可以不修身；想修身，不可以不事奉双亲；想事亲，不可以不了解人；想知人，不可以不知道天。</p><p><strong>五达道 · 三达德</strong>：天下通行的道有五，用以实行它的德有三：君臣、父子、夫妇、兄弟、朋友之交，这五者是天下通行的道；智、仁、勇三者，是天下通行的德，用以实行它的是「一」。有的人生来就知道，有的学了才知道，有的困顿后才知，但到知道时是一样的；有的人生来安行，有的为利而行，有的勉强而行，但到成功时是一样的。</p><p>孔子说：「好学接近智，力行接近仁，知耻接近勇。知道这三者，就知道怎么修身；知道修身，就知道怎么治人；知道治人，就知道怎么治理天下国家了。」</p><p><strong>九经</strong>：凡治理天下国家有九条常道：修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯。修身则道立，尊贤则不迷惑，亲亲则父兄不怨，敬大臣则不迷乱，体群臣则士人报礼厚，子庶民则百姓勉励，来百工则财用足，柔远人则四方归附，怀诸侯则天下敬畏。</p><p><strong>九经之目</strong>：斋戒明洁、盛服，非礼不动，是修身之法；去除谗言、远离美色，轻财货而重德行，是劝贤之法；尊其位、重其禄、同其好恶，是劝亲亲之法；官属盛大、任使得宜，是劝大臣之法；忠信而厚禄，是劝士之法；役使有时、赋敛轻薄，是劝百姓之法；日日省察、月月考核，所给与其事相称，是劝百工之法；送往迎来、嘉善而悯不能，是柔远人之法；继绝了的世族、兴废了的邦国、治乱持危、朝聘按时、厚往薄来，是怀诸侯之法。凡为天下国家有九经，而用以实行它的是「一」。</p><p><strong>凡事豫则立</strong>：凡事预先准备就能成立，不预备就会废败。话先说定就不会窒碍，事预先定好就不会困窘，行动先定就不会有疚，道路先定就不会走穷。在下位不得上位的信任，百姓就治不好；要得上位信任有道：不被朋友信任，就得不来上位信任；要朋友信任有道：不顺乎双亲，就得不到朋友信任；顺亲有道：反求自身而不诚，就不能顺亲；诚身有道：不明白善，就不能诚身。</p><p><strong>诚者天之道</strong>：诚，是天之道；做到诚，是人之道。诚，是不必勉强而中、不必思虑而得、从容合于中道的，那是圣人。做到诚，就是择善而坚定持守的人。</p><p><strong>博学审问慎思明辨笃行</strong>：广博地学，详细地问，慎重地思，明白地辨，笃实地行。有不学的，学了不到会就不放下；有不问的，问不到知就不放下；有不思的，思不到得就不放下；有不辨的，辨不到明就不放下；有不行的，行不到笃就不放下。别人一遍能，自己做一百遍；别人十遍能，自己做一千遍。真能照这条道去做，即使愚笨也必变明白，即使柔弱也必变刚强。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十章是全篇最长的一章，也是结构最完整的一章。它从「哀公问政」出发，一层层往里收：</p><ol><li><strong>为政在人</strong>——「取人以身，修身以道，修道以仁」（一条自上而下又自下而上的链）</li><li><strong>仁、义、礼</strong>——「仁者人也，亲亲为大；义者宜也，尊贤为大」，礼由等差而生</li><li><strong>五达道、三达德</strong>——君臣父子夫妇昆弟朋友，与知仁勇</li><li><strong>九经</strong>——治天下国家的九条常道，以及每条的做法</li><li><strong>诚</strong>——「诚者，天之道也；诚之者，人之道也」</li><li><strong>为学五步</strong>——博学、审问、慎思、明辨、笃行；以及「人一能之己百之」</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把政治收束到修身</strong>：「为政在人，取人以身」——任何治理问题，最后都落回「人」，而人的根本在修身。<strong>这是全篇最实用的一条链</strong>。</li><li><strong>它给出三组清单</strong>：五达道（人与人的五种基本关系）、三达德（知仁勇）、九经（治理的九条常道）。<strong>清单式的表达，让抽象的道有了可对表的形式。</strong></li><li><strong>「诚」在这一章正式展开</strong>：前面第 16 章说「诚之不可揜」，本章给出定义性的对照——「诚者，天之道也；诚之者，人之道也」。第 21 章的「自诚明／自明诚」正是从这里接下去的。</li><li><strong>为学五步是全篇的功夫论落点</strong>：博学、审问、慎思、明辨、笃行——<strong>从学到行，五步不缺</strong>；而后「弗措」（不到会不放下）与「人一能之己百之」，把这条路说成可走的。这一章因此不只讲「是什么」，还讲了「怎么做」。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用那条链检查</strong>：我现在做的事，卡在「人」上了吗？那我自己修得如何？（为政在人 → 取人以身 → 修身以道 → 修道以仁）</li><li><strong>对表三张清单</strong>：五达道（五种关系是否都安顿好）、三达德（知仁勇哪个最弱）、九经（若在一个组织里，哪几条没做到）。</li><li><strong>「豫则立」</strong>：手头悬着的事，有没有「言前定、事前定、行前定」？</li><li><strong>学与行的五步</strong>：我常常跳过了哪一步？（多数学问停在「学、问、思、辨」，缺「笃行」）</li><li><strong>人一能之己百之</strong>：这不是励志口号，而是「困而知之者」的正路——承认自己慢，然后用多遍补上来。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>这一章很长，但它的逻辑是一条直线：<strong>治理天下 → 在于得人 → 在于修身 → 在于道 → 在于仁。</strong></p><p>接着它把「仁」和「义」讲清楚：仁是人之所以为人（亲亲为大），义是合宜（尊贤为大）；由此生出等差与等级，礼就产生了。</p><p>然后是三张清单：<strong>五种人际关系</strong>（君臣、父子、夫妇、兄弟、朋友）、<strong>三种德</strong>（知、仁、勇）、<strong>九条常道</strong>（从修身到怀诸侯）。九经里最实用的部分，是每条「怎么做」——比如劝百姓要「时使薄敛」，劝百工要「日省月试、既禀称事」。</p><p>最后落到「诚」：<strong>诚是天之道，做到诚是人之道</strong>。而做到诚的路，是「择善而固执之」——博学、审问、慎思、明辨、笃行，学不到会不放下、问不到知不放下、行不到笃不放下。<strong>别人一遍能，我做一百遍。</strong></p><p>所以这一章既是政治的纲领，也是一个人怎么把自己练出来的说明书。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「为政在人，取人以身」——我最近遇到的「事的问题」，剥到最里面，是不是「人的问题」，再往里是不是「我自己的问题」？</li><li>三张清单（五达道／三达德／九经）——若只能挑一项先补，我挑哪一项？为什么？</li><li>「诚者，天之道也；诚之者，人之道也」——我更像「诚者」还是「诚之者」？这个判断的依据是什么？</li><li>为学五步——我最常跳过哪一步？跳过它的代价是什么？</li><li>「人一能之己百之」——这句话对我意味着安慰，还是方法？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-19">中庸·第19章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-21">中庸·第21章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',31))])}}});export{b as __pageData,z as default};
